// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/passkey/login/begin", wrapper.BeginPasskeyLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/passkey/login/finish", wrapper.FinishPasskeyLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/password", wrapper.ChangePassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/passkeys", wrapper.ListMyPasskeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/passkeys/register/begin", wrapper.BeginPasskeyRegistration)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/passkeys/register/finish", wrapper.FinishPasskeyRegistration)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/me/passkeys/{id}", wrapper.DeleteMyPasskey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/keys", wrapper.GetMyKeys)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/me/keys/mcp", wrapper.RevokeMyMcpKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/keys/mcp", wrapper.IssueMyMcpKey)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/me/keys/ingest/reissue", wrapper.ReissueMyIngestToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/telemetry-settings", wrapper.GetMyTelemetrySettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/me/telemetry-settings", wrapper.UpdateMyTelemetrySettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users", wrapper.InviteUser)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/users/{id}", wrapper.RevokeInvite)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users/{id}/invite", wrapper.ReissueInvite)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/users/{id}/password-reset", wrapper.IssuePasswordReset)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/invites/{token}", wrapper.GetInvite)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/invites/{token}/accept", wrapper.AcceptInvite)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/password-resets/{token}", wrapper.GetPasswordReset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/password-resets/{token}/complete", wrapper.CompletePasswordReset)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/version", wrapper.GetVersion)

	return m
}

