// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// BeginPasskeyLogin Begin signing in with a passkey
	// (POST /auth/passkey/login/begin)
	BeginPasskeyLogin(ctx context.Context, request BeginPasskeyLoginRequestObject) (BeginPasskeyLoginResponseObject, error)
	// FinishPasskeyLogin Finish signing in with a passkey
	// (POST /auth/passkey/login/finish)
	FinishPasskeyLogin(ctx context.Context, request FinishPasskeyLoginRequestObject) (FinishPasskeyLoginResponseObject, error)
	// GetInvite The user an invitation link was issued to
	// (GET /invites/{token})
	GetInvite(ctx context.Context, request GetInviteRequestObject) (GetInviteResponseObject, error)
	// AcceptInvite Accept the invitation by setting a password
	// (POST /invites/{token}/accept)
	AcceptInvite(ctx context.Context, request AcceptInviteRequestObject) (AcceptInviteResponseObject, error)
	// GetMe The signed-in user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetMyKeys The state of the MCP key and the collector token of the signed-in user
	// (GET /me/keys)
	GetMyKeys(ctx context.Context, request GetMyKeysRequestObject) (GetMyKeysResponseObject, error)
	// ReissueMyIngestToken Reissue the collector token of the signed-in user
	// (POST /me/keys/ingest/reissue)
	ReissueMyIngestToken(ctx context.Context, request ReissueMyIngestTokenRequestObject) (ReissueMyIngestTokenResponseObject, error)
	// RevokeMyMcpKey Revoke the MCP key of the signed-in user
	// (DELETE /me/keys/mcp)
	RevokeMyMcpKey(ctx context.Context, request RevokeMyMcpKeyRequestObject) (RevokeMyMcpKeyResponseObject, error)
	// IssueMyMcpKey Issue the MCP key of the signed-in user
	// (POST /me/keys/mcp)
	IssueMyMcpKey(ctx context.Context, request IssueMyMcpKeyRequestObject) (IssueMyMcpKeyResponseObject, error)
	// ListMyPasskeys The passkeys of the signed-in user
	// (GET /me/passkeys)
	ListMyPasskeys(ctx context.Context, request ListMyPasskeysRequestObject) (ListMyPasskeysResponseObject, error)
	// BeginPasskeyRegistration Begin adding a passkey to the signed-in user
	// (POST /me/passkeys/register/begin)
	BeginPasskeyRegistration(ctx context.Context, request BeginPasskeyRegistrationRequestObject) (BeginPasskeyRegistrationResponseObject, error)
	// FinishPasskeyRegistration Finish adding a passkey to the signed-in user
	// (POST /me/passkeys/register/finish)
	FinishPasskeyRegistration(ctx context.Context, request FinishPasskeyRegistrationRequestObject) (FinishPasskeyRegistrationResponseObject, error)
	// DeleteMyPasskey Delete a passkey of the signed-in user
	// (DELETE /me/passkeys/{id})
	DeleteMyPasskey(ctx context.Context, request DeleteMyPasskeyRequestObject) (DeleteMyPasskeyResponseObject, error)
	// ChangePassword Change the password of the signed-in user
	// (POST /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// GetMyTelemetrySettings The deny settings of the signed-in user and their version
	// (GET /me/telemetry-settings)
	GetMyTelemetrySettings(ctx context.Context, request GetMyTelemetrySettingsRequestObject) (GetMyTelemetrySettingsResponseObject, error)
	// UpdateMyTelemetrySettings Save the deny settings of the signed-in user in place of the version they were read at
	// (PUT /me/telemetry-settings)
	UpdateMyTelemetrySettings(ctx context.Context, request UpdateMyTelemetrySettingsRequestObject) (UpdateMyTelemetrySettingsResponseObject, error)
	// GetPasswordReset The user a password reset link was issued to
	// (GET /password-resets/{token})
	GetPasswordReset(ctx context.Context, request GetPasswordResetRequestObject) (GetPasswordResetResponseObject, error)
	// CompletePasswordReset Set a new password by the reset link
	// (POST /password-resets/{token}/complete)
	CompletePasswordReset(ctx context.Context, request CompletePasswordResetRequestObject) (CompletePasswordResetResponseObject, error)
	// ListUsers Every user, invited ones included
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// InviteUser Invite a user
	// (POST /users)
	InviteUser(ctx context.Context, request InviteUserRequestObject) (InviteUserResponseObject, error)
	// RevokeInvite Revoke the invitation
	// (DELETE /users/{id})
	RevokeInvite(ctx context.Context, request RevokeInviteRequestObject) (RevokeInviteResponseObject, error)
	// ReissueInvite Reissue the invitation link
	// (POST /users/{id}/invite)
	ReissueInvite(ctx context.Context, request ReissueInviteRequestObject) (ReissueInviteResponseObject, error)
	// IssuePasswordReset Issue a password reset link to another active user
	// (POST /users/{id}/password-reset)
	IssuePasswordReset(ctx context.Context, request IssuePasswordResetRequestObject) (IssuePasswordResetResponseObject, error)
	// GetVersion Service build version
	// (GET /version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request, params LoginParams) {
	var request LoginRequestObject

	request.Params = params

	var body LoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

